  var row=jdbc.queryForMap("select * from fa_posting_rule where tenant_id=:tenantId and book_id=:book and source_type=:type and event_key=:event",b);audit.record("FINANCE_POSTING_RULE_CONFIGURED","FA_BOOK",in.bookId(),json(in));return output(row);
