  var rules=jdbc.queryForList("select r.*,d.code as debit_code,d.cash_account as debit_cash,c.code as credit_code,c.cash_account as credit_cash from fa_posting_rule r join fa_account d on d.tenant_id=r.tenant_id and d.id=r.debit_account_id and d.enabled join fa_account c on c.tenant_id=r.tenant_id and c.id=r.credit_account_id and c.enabled where r.tenant_id=:tenantId and r.book_id=:book and r.source_type=:type and r.event_key=:event and r.enabled",b);
  if(rules.isEmpty())return sourceStatus(b,"PENDING_MAPPING",bookId);var rule=rules.getFirst();if((Boolean.TRUE.equals(rule.get("debit_cash"))||Boolean.TRUE.equals(rule.get("credit_cash")))&&rule.get("cash_flow_category")==null)return sourceStatus(b,"PENDING_MAPPING",bookId);var day=date(event,"accounting_date");
  if(day.isBefore(date(book,"start_month")))return sourceStatus(b,"PENDING_PERIOD",bookId);ensurePeriod(p,bookId,YearMonth.from(day).atDay(1));if(!"OPEN".equals(periodRow(p,bookId,YearMonth.from(day).atDay(1)).get("status")))return sourceStatus(b,"PENDING_PERIOD",bookId);
