 private static void requireRecurringSchedule(RecurringSource source,LocalDate start,LocalDate end,BigDecimal monthly) {if(start.isBefore(source.firstMonth())||end.isAfter(source.lastMonth()))throw bad("计划月份超出真实来源已确认投用/受益期间");if(source.standard()!=null&&monthly.compareTo(source.standard())!=0)throw bad("计划月金额必须符合真实来源已批准的直线计提政策："+source.standard().toPlainString());}
 /** Called by both business settlement and accounting plans before either takes a book lock. */
 Map<String,Object> lockBudgetOwner(TenantPrincipal p,Map<String,Object> document) {
  jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,103))",base(p).addValue("key",p.tenantId()+":financial-budget"),Object.class);
  var owner=document;UUID parent=uuid(document,"recognized_source_document_id");if(parent!=null){var owners=jdbc.queryForList("select * from fo_document where tenant_id=:tenantId and id=:owner",base(p).addValue("owner",parent));if(owners.isEmpty())throw conflict("预算真实购买来源缺失");owner=owners.getFirst();}
  access.requireOrgScope(uuid(owner,"hotel_id"));if(!Objects.equals(uuid(document,"company_id"),uuid(owner,"company_id")))throw conflict("预算来源与当前财务事项的冻结法人不符");UUID budget=uuid(owner,"budget_id");if(budget==null)return owner;
  var b=base(p).addValue("budget",budget);var rows=jdbc.queryForList("select * from fo_budget where tenant_id=:tenantId and id=:budget for update",b);if(rows.isEmpty()||!uuid(owner,"hotel_id").equals(uuid(rows.getFirst(),"hotel_id"))||!YearMonth.from(date(owner,"business_date")).atDay(1).equals(date(rows.getFirst(),"month")))throw conflict("预算不属于真实来源组织和承诺期间");return owner;
 }
 /** A transfer of one existing reservation, never a second budget charge or an implicit payment. */
 void convertSourceBudgetUsage(TenantPrincipal p,Map<String,Object> document,BigDecimal amount) {
  var owner=lockBudgetOwner(p,document);if(uuid(owner,"budget_id")==null)return;var b=base(p).addValue("owner",owner.get("id")).addValue("amount",amount);var usage=jdbc.queryForList("select * from fo_budget_usage where tenant_id=:tenantId and document_id=:owner for update",b);
  if(amount.signum()<=0||usage.isEmpty()||!uuid(owner,"budget_id").equals(uuid(usage.getFirst(),"budget_id"))||money(usage.getFirst(),"committed").compareTo(amount)<0)throw conflict("预算承诺余额不足以转实际，需核对真实来源");jdbc.update("update fo_budget_usage set committed=committed-:amount,actual=actual+:amount,updated_at=now() where tenant_id=:tenantId and document_id=:owner",b);
 }
 private Map<String,Object> recurringPlan(TenantPrincipal p,UUID id) {var rows=jdbc.queryForList("select * from fa_recurring_plan where tenant_id=:tenantId and id=:id",base(p).addValue("id",id));if(rows.isEmpty())throw missing();book(p,uuid(rows.getFirst(),"book_id"));if(isPayroll(rows.getFirst()))access.requirePermission("finance.payroll");return rows.getFirst();}

 public Map<String,Object> sourceChecks(UUID bookId,String month) {var p=prepareRead();book(p,bookId);return list(jdbc.queryForList("select * from fa_source_check where tenant_id=:tenantId and book_id=:book and month=:month order by source_type",base(p).addValue("book",bookId).addValue("month",parseMonth(month))));}
 public Map<String,Object> saveSourceCheck(FinanceAccountingModels.SourceCheck in) {
  var p=prepare(CLOSE);var book=book(p,in.bookId());var month=parseMonth(in.month());lock(p,"book:"+in.bookId());requireOpen(p,book,month);
  if(in.complete()&&(in.expectedCount()==null||!in.expectedCount().equals(in.actualCount())))throw bad("来源数量未核对一致，不能确认完成");var b=base(p).addValue("book",in.bookId()).addValue("month",month).addValue("type",in.sourceType());var rows=jdbc.queryForList("select * from fa_source_check where tenant_id=:tenantId and book_id=:book and month=:month and source_type=:type for update",b);expect(rows.isEmpty()?-1:integer(rows.getFirst(),"version"),in.expectedVersion());
  b.addValue("complete",in.complete()).addValue("expected",in.expectedCount()).addValue("actual",in.actualCount()).addValue("note",in.note());jdbc.update("insert into fa_source_check(tenant_id,book_id,month,source_type,complete,expected_count,actual_count,note,confirmed_by) values(:tenantId,:book,:month,:type,:complete,:expected,:actual,:note,:actorId) on conflict(tenant_id,book_id,month,source_type) do update set complete=excluded.complete,expected_count=excluded.expected_count,actual_count=excluded.actual_count,note=excluded.note,confirmed_by=excluded.confirmed_by,version=fa_source_check.version+1",b);audit.record("FINANCE_SOURCE_COVERAGE_CONFIRMED","FA_BOOK",in.bookId(),json(in));return output(jdbc.queryForMap("select * from fa_source_check where tenant_id=:tenantId and book_id=:book and month=:month and source_type=:type",b));
 }
 public Map<String,Object> periodCheck(UUID bookId,String month) {var p=prepareRead();var book=book(p,bookId);lock(p,"book:"+bookId);return checkFor(p,book,parseMonth(month));}
 private Map<String,Object> checkFor(TenantPrincipal p,Map<String,Object> book,LocalDate month) {
  UUID bookId=uuid(book,"id");if(month.isBefore(date(book,"start_month")))throw bad("期间早于账套启用日");ensurePeriod(p,bookId,month);var period=periodRow(p,bookId,month);var b=base(p).addValue("book",bookId).addValue("hotel",book.get("hotel_id")).addValue("month",month).addValue("end",month.plusMonths(1)).addValue("start",book.get("start_month"));
  var checks=new ArrayList<Map<String,Object>>();
  addCheck(checks,"OPENING_BALANCE",count("select count(*) from fa_import_batch where tenant_id=:tenantId and book_id=:book",b)==1,"期初余额未正式导入并核对");
  long sourceCount=count("select count(*) from fa_source_check where tenant_id=:tenantId and book_id=:book and month=:month",b);long incomplete=count("select count(*) from fa_source_check where tenant_id=:tenantId and book_id=:book and month=:month and not complete",b);addCheck(checks,"SOURCE_COVERAGE",sourceCount>0&&incomplete==0,"请确认本期所有适用来源、计提/折旧/摊销任务及差异核对清单，空清单不能证明完整");
  addCheck(checks,"PENDING_SOURCE_EVENTS",count("select count(*) from fa_source_event where tenant_id=:tenantId and hotel_id=:hotel and accounting_date>=:month and accounting_date<:end and status<>'POSTED'",b)==0,"存在缺映射/锁期/未过账来源事件");
  addCheck(checks,"UNPOSTED_VOUCHERS",count("select count(*) from fa_voucher where tenant_id=:tenantId and book_id=:book and month=:month and status<>'POSTED'",b)==0,"存在尚未审核过账的凭证");
  addCheck(checks,"RECURRING_TASKS",count("select count(*) from fa_recurring_plan r where r.tenant_id=:tenantId and r.book_id=:book and r.active and r.start_month<=:month and r.end_month>=:month and (select coalesce(sum(x.amount),0) from fa_recurring_run x where x.tenant_id=r.tenant_id and x.plan_id=r.id and x.month<:month)<r.total_amount and not exists(select 1 from fa_recurring_run x join fa_voucher v on v.tenant_id=x.tenant_id and v.id=x.voucher_id where x.tenant_id=r.tenant_id and x.plan_id=r.id and x.month=:month and v.status='POSTED')",b)==0,"存在本月未执行或未过账的折旧/摊销/分摊/计提计划");
  addCheck(checks,"PRIOR_PERIODS",count("select count(*) from generate_series(cast(:start as date),cast(:month as date)-interval '1 month',interval '1 month') m where not exists(select 1 from fa_period p where p.tenant_id=:tenantId and p.book_id=:book and p.month=m::date and p.status='CLOSED')",b)==0,"前期尚未关账");
  var totals=jdbc.queryForMap("select coalesce(sum(l.debit),0) as debit,coalesce(sum(l.credit),0) as credit from fa_voucher_line l join fa_voucher v on v.tenant_id=l.tenant_id and v.id=l.voucher_id where v.tenant_id=:tenantId and v.book_id=:book and v.accounting_date<:end and v.status='POSTED'",b);addCheck(checks,"TRIAL_BALANCE",money(totals,"debit").compareTo(money(totals,"credit"))==0,"已过账借贷不平衡");
  addCheck(checks,"CASH_FLOW_CLASSIFICATION",count("select count(*) from fa_voucher_line l join fa_voucher v on v.tenant_id=l.tenant_id and v.id=l.voucher_id join fa_account a on a.tenant_id=l.tenant_id and a.id=l.account_id where v.tenant_id=:tenantId and v.book_id=:book and v.month=:month and v.status='POSTED' and a.cash_account and l.cash_flow_category is null",b)==0,"现金/银行分录缺少现金流分类");
  if(!new FinanceControlGuard(jdbc).table("fcl_register"))addCheck(checks,"BANK_RECONCILIATION",count("select count(*) from fo_bank_transaction t join fo_bank_account a on a.tenant_id=t.tenant_id and a.id=t.bank_account_id left join lateral(select coalesce(sum(m.amount),0) as matched_amount,count(*) as match_count from fo_bank_match m where m.tenant_id=t.tenant_id and m.transaction_id=t.id) matched on true left join fo_bank_explanation e on e.tenant_id=t.tenant_id and e.transaction_id=t.id where t.tenant_id=:tenantId and a.hotel_id=:hotel and t.occurred_on>=:month and t.occurred_on<:end and matched.matched_amount<>t.amount and not(coalesce(e.transaction_hash_snapshot=t.source_hash and e.matched_amount_snapshot=matched.matched_amount and e.match_count_snapshot=matched.match_count,false))",b)==0,"本法人账套组织本月银行流水存在未完全匹配且尚无有效逐笔差异解释的项目");
  checks.addAll(FinanceCloseV2.extraChecks(jdbc,p,book,month));
  if(month.getMonthValue()==12) addCheck(checks,"YEAR_END_TRANSFER",yearProfitNet(p,bookId,month.getYear()).values().stream().allMatch(v->v.signum()==0),"12月须完成独立审核的损益结转且无后续未结转损益");
  boolean complete=checks.stream().allMatch(c->Boolean.TRUE.equals(c.get("passed")));return output(Map.of("bookId",bookId,"month",YearMonth.from(month).toString(),"status",period.get("status"),"version",period.get("version"),"complete",complete,"canClose",complete&&"OPEN".equals(period.get("status")),"checks",checks));
 }
 private static void addCheck(List<Map<String,Object>> checks,String code,boolean passed,String message) {checks.add(Map.of("code",code,"passed",passed,"message",passed?"已核对":message));}
 public Map<String,Object> close(FinanceAccountingModels.Period in,boolean reopen) {
  var p=prepare(CLOSE);var book=book(p,in.bookId());lock(p,"book:"+in.bookId());var month=parseMonth(in.month());ensurePeriod(p,in.bookId(),month);var row=periodRow(p,in.bookId(),month);expect(integer(row,"version"),in.expectedVersion());
  var b=base(p).addValue("book",in.bookId()).addValue("month",month);if(reopen) {if(!"CLOSED".equals(row.get("status")))throw conflict("期间未关账");if(count("select count(*) from fa_period where tenant_id=:tenantId and book_id=:book and month>:month and status='CLOSED'",b)>0)throw conflict("后续期间已关账，须按逆序重开");jdbc.update("update fa_period set status='OPEN',version=version+1,closed_by=null,closed_at=null where tenant_id=:tenantId and book_id=:book and month=:month",b);}
  else {if(!"OPEN".equals(row.get("status")))throw conflict("期间已经关账");var check=checkFor(p,book,month);if(!Boolean.TRUE.equals(check.get("canClose")))throw conflict("月结检查未通过，请处理来源缺项和未过账凭证");var snapshot=new LinkedHashMap<>(reportsFor(p,book,month,true));snapshot.put("status","FINAL");snapshot.put("frozenAt",Instant.now().toString());jdbc.update("update fa_period set status='CLOSED',version=version+1,closed_by=:actorId,closed_at=now(),close_snapshot=cast(:snapshot as jsonb) where tenant_id=:tenantId and book_id=:book and month=:month",b.addValue("snapshot",json(snapshot)));}
  audit.record(reopen?"FINANCE_PERIOD_REOPENED":"FINANCE_PERIOD_CLOSED","FA_BOOK",in.bookId(),json(in));return checkFor(p,book,month);
 }

 public Map<String,Object> imports(FinanceAccountingModels.Import in) {
  var p=prepare(CONFIG);var book=book(p,in.bookId());lock(p,"book:"+in.bookId());BigDecimal debit=BigDecimal.ZERO,credit=BigDecimal.ZERO;Set<String> codes=new HashSet<>();var validated=new ArrayList<Map<String,Object>>();
  for(var row:in.balances()) {if(!codes.add(row.accountCode()))throw bad("期初科目重复");var a=account(p,in.bookId(),row.accountCode(),true);if(row.debit()==null||row.credit()==null||row.debit().signum()<0||row.credit().signum()<0||row.debit().scale()>2||row.credit().scale()>2||row.debit().precision()>18||row.credit().precision()>18||row.debit().signum()>0&&row.credit().signum()>0)throw bad("期初金额格式错误");debit=debit.add(row.debit());credit=credit.add(row.credit());validated.add(Map.of("accountId",a.get("id"),"accountCode",row.accountCode(),"debit",row.debit(),"credit",row.credit()));}
  boolean balanced=debit.compareTo(credit)==0;var reconciliation=Map.of("debit",debit,"credit",credit,"difference",debit.subtract(credit),"balanced",balanced,"rows",validated,"sourceReference",in.sourceReference(),"checks",in.reconciliation());
  if("PREVIEW".equals(in.mode()))return output(Map.of("mode","PREVIEW","committed",false,"reconciliation",reconciliation));if(!balanced)throw bad("期初借贷不平衡，整批未导入");if(in.reconciliation().isEmpty())throw bad("请提供真实来源核对说明");
  String hash=FinanceService.hash(json(Map.of("book",in.bookId(),"reference",in.sourceReference(),"rows",validated,"checks",new TreeMap<>(in.reconciliation()))));var b=base(p).addValue("book",in.bookId()).addValue("id",in.requestId());var prior=jdbc.queryForList("select * from fa_import_batch where tenant_id=:tenantId and (id=:id or book_id=:book)",b);
  if(!prior.isEmpty()) {if(prior.size()!=1||!in.requestId().equals(uuid(prior.getFirst(),"id"))||!hash.equals(prior.getFirst().get("request_hash")))throw conflict("已有不同期初批次；不得覆盖已确认期初");return output(Map.of("mode","COMMIT","committed",true,"replayed",true,"batchId",in.requestId(),"reconciliation",reconciliation));}
  if(count("select count(*) from fa_voucher where tenant_id=:tenantId and book_id=:book and status='POSTED'",b)>0)throw conflict("账套已有已过账凭证，不能回写期初");if(count("select count(*) from fa_period where tenant_id=:tenantId and book_id=:book and status='CLOSED'",b)>0)throw conflict("账套已有已结期间，不能回写期初");
  jdbc.update("insert into fa_import_batch(id,tenant_id,book_id,source_reference,request_hash,imported_by,reconciliation) values(:id,:tenantId,:book,:reference,:hash,:actorId,cast(:reconciliation as jsonb))",b.addValue("reference",in.sourceReference()).addValue("hash",hash).addValue("reconciliation",json(reconciliation)));
  for(var row:validated)jdbc.update("insert into fa_opening_balance(tenant_id,book_id,account_id,batch_id,debit,credit) values(:tenantId,:book,:account,:id,:debit,:credit)",b.addValue("account",row.get("accountId")).addValue("debit",row.get("debit")).addValue("credit",row.get("credit")));
  audit.record("FINANCE_OPENING_BALANCES_IMPORTED","FA_BOOK",in.bookId(),json(Map.of("batchId",in.requestId(),"source",in.sourceReference(),"rows",validated.size())));return output(Map.of("mode","COMMIT","committed",true,"replayed",false,"batchId",in.requestId(),"reconciliation",reconciliation));
 }

 public Map<String,Object> yearClose(FinanceAccountingModels.YearClose in) {
  var p=prepare(WRITE,CLOSE);var book=book(p,in.bookId());lock(p,"book:"+in.bookId());var retained=account(p,in.bookId(),in.retainedEarningsAccountCode(),true);if(!"EQUITY".equals(retained.get("category")))throw bad("结转目标必须是权益科目");var b=base(p).addValue("book",in.bookId()).addValue("month",LocalDate.of(in.year(),12,1)).addValue("id",in.requestId());
  var existing=jdbc.queryForList("select id,summary from fa_voucher where tenant_id=:tenantId and book_id=:book and month=:month and kind='YEAR_CLOSE' and (reversed_by_id is null or not exists(select 1 from fa_voucher rv where rv.tenant_id=fa_voucher.tenant_id and rv.id=fa_voucher.reversed_by_id and rv.status='POSTED'))",b);if(!existing.isEmpty()){if(in.requestId().equals(uuid(existing.getFirst(),"id"))){if(!in.summary().equals(existing.getFirst().get("summary"))||count("select count(*) from fa_voucher_line where tenant_id=:tenantId and voucher_id=:id and account_id=:retained",b.addValue("retained",retained.get("id")))!=1)throw conflict("同一年结请求的科目或说明已经变更");return detail(p,in.requestId());}throw conflict("本年度已有损益结转凭证");}
  var net=yearProfitNet(p,in.bookId(),in.year());var lines=new ArrayList<FinanceAccountingModels.Line>();BigDecimal balancing=BigDecimal.ZERO;
  if(new FinanceAuxiliaryDimensions(jdbc).installed()){
   var values=jdbc.queryForList("select code,auxiliary,sum(net) net from (select a.code,l.auxiliary,l.debit-l.credit net from fa_account a join fa_voucher_line l on l.tenant_id=a.tenant_id and l.account_id=a.id join fa_voucher v on v.tenant_id=l.tenant_id and v.id=l.voucher_id where a.tenant_id=:tenantId and a.book_id=:book and a.category in ('REVENUE','EXPENSE') and v.status='POSTED' and v.accounting_date>=:start and v.accounting_date<:end union all select a.code,'{}'::jsonb,o.debit-o.credit from fa_account a join fa_book k on k.tenant_id=a.tenant_id and k.id=a.book_id join fa_opening_balance o on o.tenant_id=a.tenant_id and o.account_id=a.id where a.tenant_id=:tenantId and a.book_id=:book and a.category in ('REVENUE','EXPENSE') and extract(year from k.start_month)=:year) actual group by code,auxiliary order by code,auxiliary::text",b.addValue("start",LocalDate.of(in.year(),1,1)).addValue("end",LocalDate.of(in.year()+1,1,1)).addValue("year",in.year()));
   for(var entry:values){var amount=money(entry,"net");if(amount.signum()==0)continue;lines.add(new FinanceAccountingModels.Line(str(entry,"code"),amount.signum()<0?amount.negate():BigDecimal.ZERO,amount.signum()>0?amount:BigDecimal.ZERO,in.summary(),null,jsonMap(entry.get("auxiliary"))));balancing=balancing.add(amount);}
  }else for(var entry:net.entrySet()){var amount=entry.getValue();if(amount.signum()==0)continue;lines.add(new FinanceAccountingModels.Line(entry.getKey(),amount.signum()<0?amount.negate():BigDecimal.ZERO,amount.signum()>0?amount:BigDecimal.ZERO,in.summary(),null));balancing=balancing.add(amount);}
  if(lines.isEmpty())throw bad("本年度无待结转损益");lines.add(new FinanceAccountingModels.Line(in.retainedEarningsAccountCode(),balancing.signum()>0?balancing:BigDecimal.ZERO,balancing.signum()<0?balancing.negate():BigDecimal.ZERO,in.summary(),null));if(balancing.signum()==0)lines.removeLast();
  return createVoucherFor(p,new FinanceAccountingModels.Voucher(in.requestId(),in.bookId(),LocalDate.of(in.year(),12,31),LocalDate.of(in.year(),12,31),in.summary(),lines),"YEAR_CLOSE",null,null);
 }
 private Map<String,BigDecimal> yearProfitNet(TenantPrincipal p,UUID bookId,int year) {
  var rows=jdbc.queryForList("select a.code,coalesce(t.net,0)+case when extract(year from k.start_month)=:year then coalesce(o.debit-o.credit,0) else 0 end as net from fa_account a join fa_book k on k.tenant_id=a.tenant_id and k.id=a.book_id left join fa_opening_balance o on o.tenant_id=a.tenant_id and o.account_id=a.id left join lateral(select sum(l.debit-l.credit) as net from fa_voucher_line l join fa_voucher v on v.tenant_id=l.tenant_id and v.id=l.voucher_id where l.tenant_id=a.tenant_id and l.account_id=a.id and v.status='POSTED' and v.accounting_date>=:start and v.accounting_date<:end) t on true where a.tenant_id=:tenantId and a.book_id=:book and a.category in ('REVENUE','EXPENSE')",base(p).addValue("book",bookId).addValue("year",year).addValue("start",LocalDate.of(year,1,1)).addValue("end",LocalDate.of(year+1,1,1)));var result=new LinkedHashMap<String,BigDecimal>();rows.forEach(r->result.put(str(r,"code"),money(r,"net")));return result;
 }

